import { readFile } from 'node:fs';
import { promisify } from 'node:util';

readFile('menu.txt', 'utf8', (err, isi) => {
  console.log('callback:', err, isi.trim());
});
readFile('hilang.txt', 'utf8', (err) => {
  console.log('callback gagal:', err.code);
});

function bagi(a, b) {
  return new Promise((resolve, reject) => {
    if (b === 0) reject(new Error('Tidak bisa dibagi nol'));
    else resolve(a / b);
  });
}
console.log('hasil bagi:', await bagi(10, 4));
const baca = promisify(readFile);
console.log('promisify:', (await baca('menu.txt', 'utf8')).trim());

