console.log('Pesanan siap');
function masak(menu) {
  return new Promise((resolve, reject) => {
    if (menu === '') {
      reject(new Error('Menu kosong'));
      return;
    }
    setTimeout(() => resolve(`${menu} siap`), 10);
  });
}
console.log(await masak('Kopi Susu'));
try {
  await masak('');
} catch (e) {
  console.log('Gagal:', e.message);
}

