function cekStok(jumlah) {
  return new Promise((resolve, reject) => {
    if (jumlah > 0) resolve('Stok cukup');
    else reject(new Error('Stok habis'));
  });
}
console.log(await cekStok(3));
try {
  await cekStok(0);
} catch (e) {
  console.log(e.message);
}
